/**
 * Demo-only stand-in for the UIDrift API, used to record the walkthrough video and screenshots
 * without MongoDB or Redis. It serves reports generated by the real analysis engine
 * (`npm run demo:fixtures -w server`), simulates live progress over SSE, and enforces login with a
 * cookie exactly like the real API (so the Next.js login gate behaves the same).
 *
 *   node scripts/demo/stub-api.mjs [port=4000]
 */
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';

const load = (name) =>
  JSON.parse(readFileSync(new URL(`./fixtures/${name}.json`, import.meta.url), 'utf8'));
const FIX = { website: load('website'), source: load('source'), after: load('source-after') };
const PORT = Number(process.argv[2] ?? 4000);
const USER = { id: 'u-demo', email: 'demo@uidrift.dev', name: 'Demo User' };
const COOKIE = 'uidrift_token=demo-session';

const id = (n) => `64b7f0c2a1b2c3d4e5f6${String(n).padStart(4, '0')}`;
const day = (n) => new Date(Date.now() - n * 86_400_000).toISOString();

/** Scans the "database" starts with (mirrors the seed script). */
const scans = new Map();
function addScan(n, fixture, extra) {
  scans.set(id(n), {
    id: id(n),
    kind: fixture.kind,
    url: fixture.url,
    domain: fixture.domain,
    insightsEngine: 'rules',
    status: 'done',
    progress: { pagesDone: 1, pagesTotal: 1, step: 'Done' },
    pagesScanned: fixture.pagesScanned,
    isDemo: false,
    isPublic: false,
    score: fixture.score.overall,
    report: fixture,
    ...extra,
  });
}
addScan(1, FIX.website, { isDemo: true, createdAt: day(1) });
addScan(2, FIX.source, { isDemo: true, createdAt: day(1) });
addScan(3, FIX.source, { owner: true, createdAt: day(21) });
addScan(4, FIX.after, { owner: true, createdAt: day(3) });
addScan(5, FIX.website, { owner: true, createdAt: day(2) });

let counter = 100;
const timelines = new Map();

function timeline(kind, fixture) {
  const steps =
    kind === 'source'
      ? [
          [0, 'queued', 'Queued', 0, 'Queued'],
          [700, 'page_started', 'Reading uploaded files', 0, 'Reading files'],
          [
            1800,
            'page_done',
            `Parsing ${fixture.source.filesAnalyzed} style and markup files`,
            1,
            'Parsing source',
          ],
          [
            3200,
            'analysing',
            `Grouping component definitions from ${fixture.source.styleBlocks} style blocks`,
            1,
            'Analysing',
          ],
          [5200, 'done', `Done — score ${fixture.score.overall}`, 1, 'Done'],
        ]
      : [
          [0, 'queued', 'Queued', 0, 'Queued'],
          ...fixture.pagesScanned.flatMap((p, i) => [
            [
              600 + i * 1300,
              'page_started',
              `Crawling ${p}`,
              i,
              `Crawling page ${i + 1} of ${fixture.pagesScanned.length}`,
            ],
            [
              1600 + i * 1300,
              'page_done',
              `Scanned ${p}`,
              i + 1,
              `Crawled ${i + 1} of ${fixture.pagesScanned.length}`,
            ],
          ]),
          [
            1900 + fixture.pagesScanned.length * 1300,
            'analysing',
            'Fingerprinting and grouping components',
            fixture.pagesScanned.length,
            'Analysing',
          ],
          [
            3400 + fixture.pagesScanned.length * 1300,
            'done',
            `Done — score ${fixture.score.overall}`,
            fixture.pagesScanned.length,
            'Done',
          ],
        ];
  const total = kind === 'source' ? 1 : fixture.pagesScanned.length;
  return steps.map(([t, type, message, done, step]) => ({
    t,
    type,
    message,
    progress: { pagesDone: done, pagesTotal: total, step },
  }));
}

const STATUS = {
  queued: 'queued',
  page_started: 'crawling',
  page_done: 'crawling',
  analysing: 'analysing',
  done: 'done',
};

function current(scan) {
  const tl = timelines.get(scan.id);
  if (!tl) return scan;
  const elapsed = Date.now() - tl.start;
  const last = [...tl.steps].reverse().find((s) => s.t <= elapsed) ?? tl.steps[0];
  return { ...scan, status: STATUS[last.type], progress: last.progress };
}

const dto = (s) => {
  const { report: _r, owner: _o, ...rest } = current(s);
  return rest;
};

function readBody(req) {
  return new Promise((resolve) => {
    let data = '';
    req.on('data', (c) => (data += c));
    req.on('end', () => {
      try {
        resolve(JSON.parse(data || '{}'));
      } catch {
        resolve({});
      }
    });
  });
}

createServer(async (req, res) => {
  const json = (body, status = 200, headers = {}) =>
    res
      .writeHead(status, { 'content-type': 'application/json', ...headers })
      .end(JSON.stringify(body));
  const url = (req.url ?? '').split('?')[0];
  const signedIn = (req.headers.cookie ?? '').includes(COOKIE);

  if (url === '/api/v1/health') return json({ status: 'ok', db: true, redis: true });
  if (url === '/api/v1/me') return json({ user: signedIn ? USER : null });
  if (url === '/api/v1/auth/login' || url === '/api/v1/auth/signup') {
    await readBody(req);
    return json({ user: USER }, url.endsWith('signup') ? 201 : 200, {
      'set-cookie': `${COOKIE}; Path=/; HttpOnly; SameSite=Lax`,
    });
  }
  if (url === '/api/v1/auth/logout')
    return json({ ok: true }, 200, { 'set-cookie': 'uidrift_token=; Path=/; Max-Age=0' });
  if (!signedIn) return json({ error: { code: 'UNAUTHORIZED', message: 'Please log in.' } }, 401);

  if (url === '/api/v1/demos') {
    return json({
      demos: [...scans.values()]
        .filter((s) => s.isDemo)
        .map((s) => ({ scanId: s.id, kind: s.kind, url: s.url, domain: s.domain, score: s.score })),
    });
  }
  if (url === '/api/v1/me/scans') {
    return json({
      scans: [...scans.values()]
        .filter((s) => s.owner)
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
        .map(dto),
    });
  }
  if ((url === '/api/v1/scans' || url === '/api/v1/scans/source') && req.method === 'POST') {
    const body = await readBody(req);
    const source = url.endsWith('/source');
    const fixture = source ? FIX.source : FIX.website;
    const n = ++counter;
    const label = source ? (body.source?.label ?? body.source?.repo ?? 'source') : body.url;
    addScan(n, fixture, {
      owner: true,
      url: label,
      domain: source ? fixture.domain : new URL(body.url).hostname.replace(/^www\./, ''),
      insightsEngine: body.llm ? 'llm' : 'rules',
      createdAt: new Date().toISOString(),
    });
    timelines.set(id(n), {
      start: Date.now(),
      steps: timeline(source ? 'source' : 'url', fixture),
    });
    return json({ scanId: id(n), scan: dto(scans.get(id(n))) }, 202);
  }

  const m = url.match(/^\/api\/v1\/(scans|reports)\/([a-f0-9]{24})(\/events)?$/);
  const scan = m && scans.get(m[2]);
  if (m && !scan) return json({ error: { code: 'NOT_FOUND', message: 'Scan not found.' } }, 404);
  if (m && m[1] === 'reports') {
    if (current(scan).status !== 'done')
      return json({ error: { code: 'REPORT_NOT_READY', message: 'Not ready.' } }, 409);
    const { url: u, domain, pagesScanned, ...body } = scan.report;
    return json({
      report: {
        ...body,
        id: `r-${scan.id}`,
        scanId: scan.id,
        url: scan.url ?? u,
        domain: scan.domain ?? domain,
        pagesScanned,
        createdAt: scan.createdAt,
      },
    });
  }
  if (m && m[3]) {
    res.writeHead(200, {
      'content-type': 'text/event-stream',
      'cache-control': 'no-cache, no-transform',
      'x-accel-buffering': 'no',
    });
    res.write(`event: snapshot\ndata: ${JSON.stringify(dto(scan))}\n\n`);
    const tl = timelines.get(scan.id);
    if (!tl || current(scan).status === 'done') return res.end();
    const elapsed = Date.now() - tl.start;
    const timers = tl.steps.map((s) =>
      setTimeout(
        () => {
          const e = {
            type: s.type,
            scanId: scan.id,
            message: s.message,
            progress: s.progress,
            at: new Date().toISOString(),
          };
          res.write(`event: ${s.type}\ndata: ${JSON.stringify(e)}\n\n`);
          if (s.type === 'done') res.end();
        },
        Math.max(0, s.t - elapsed),
      ),
    );
    req.on('close', () => timers.forEach(clearTimeout));
    return;
  }
  if (m) return json({ scan: dto(scan) });
  json({ error: { code: 'NOT_FOUND', message: 'Not found in demo stub.' } }, 404);
}).listen(PORT, '127.0.0.1', () => console.log(`demo stub API on :${PORT}`));
